import { describe, expect, test } from "bun:test"
import { MIME, ext, field, httpStory, isWebm, markdown, mimeFor, siblingsOf, sizeOf, stem } from "./upload.ts"

describe("the mime table", () => {
  test("shots speak their types", () => {
    expect(mimeFor("before-dismiss.png")).toBe("image/png")
    expect(mimeFor("record.mp4")).toBe("video/mp4")
    expect(mimeFor("clip.webm")).toBe("video/webm")
    expect(mimeFor("photo.JPEG")).toBe("image/jpeg")
    expect(mimeFor("anim.gif")).toBe("image/gif")
    expect(mimeFor("notes.pdf")).toBe("application/pdf")
  })

  test("unknown is null — refused locally, before GitHub sees it", () => {
    expect(mimeFor("cursed.svg")).toBeNull()
    expect(mimeFor("notes.txt")).toBeNull()
    expect(mimeFor("no-extension")).toBeNull()
    expect(mimeFor("trailingdot.")).toBeNull()
    expect(mimeFor(".dotfile")).toBeNull()
  })

})

describe("siblingsOf — what the transcode target could clobber", () => {
  test("the exact name answers to itself", () => {
    expect(siblingsOf(new Set(["clip.mp4"]), "clip.mp4")).toEqual(["clip.mp4"])
  })

  test("APFS lies about case: the clobberable file answers to its own spelling", () => {
    expect(siblingsOf(new Set(["Clip.mp4"]), "clip.mp4")).toEqual(["Clip.mp4"])
    expect(siblingsOf(new Set(["CLIP.MP4"]), "clip.mp4")).toEqual(["CLIP.MP4"])
  })

  test("every case-folded twin is named, never half-withheld", () => {
    expect(siblingsOf(new Set(["Clip.mp4", "clip.MP4", "other.png"]), "clip.mp4").sort()).toEqual([
      "Clip.mp4",
      "clip.MP4",
    ])
  })

  test("no sibling → empty", () => {
    expect(siblingsOf(new Set(["other.png", "clip.webm"]), "clip.mp4")).toEqual([])
    expect(siblingsOf(new Set(), "clip.mp4")).toEqual([])
  })
})

describe("webm detection", () => {
  test("only webm transcodes — case-insensitively", () => {
    expect(isWebm("take.webm")).toBe(true)
    expect(isWebm("TAKE.WEBM")).toBe(true)
    expect(isWebm("take.mp4")).toBe(false)
    expect(isWebm("webm-as-png.png")).toBe(false)
  })
})

describe("stem", () => {
  test("strips the known extension, keeps the rest", () => {
    expect(stem("before-dismiss.png")).toBe("before-dismiss")
    expect(stem("a.PNG")).toBe("a")
    expect(stem("noext")).toBe("noext")
  })
})

describe("markdown shaping", () => {
  const landed = [
    { file: "before.png", url: "https://u/1" },
    { file: "record.mp4", url: "https://u/2" },
    { file: "after.png", url: "https://u/3" },
  ]

  test("an image embeds with the stem as alt", () => {
    expect(markdown([landed[0]!])).toBe("![before](https://u/1)")
  })

  test("a video is the bare URL — image syntax renders no player", () => {
    expect(markdown([landed[1]!])).toBe("https://u/2")
  })

  test("a pdf is bare too — image syntax renders a broken image icon", () => {
    expect(markdown([{ file: "notes.pdf", url: "https://u/4" }])).toBe("https://u/4")
  })

  test("brackets in a filename can't break the image syntax", () => {
    expect(markdown([{ file: "we[ird]name.png", url: "https://u/5" }])).toBe(
      "![we\\[ird\\]name](https://u/5)",
    )
    expect(markdown([{ file: "a\\b.png", url: "https://u/6" }])).toBe("![a\\\\b](https://u/6)")
  })

  test("order kept; blank line between; no trailing newline", () => {
    expect(markdown(landed)).toBe("![before](https://u/1)\n\nhttps://u/2\n\n![after](https://u/3)")
  })

  test("nothing landed → nothing on stdout", () => {
    expect(markdown([])).toBe("")
  })
})

describe("http stories", () => {
  test("401/403 is the auth story", () => {
    expect(httpStory(401, "")).toContain("gh auth login")
    expect(httpStory(403, "")).toContain("HTTP 403")
  })

  test("404 is the repo/push-rights story — and can't send you to the node id", () => {
    expect(httpStory(404, "")).toMatch(/push rights/)
    expect(httpStory(404, "")).toContain("gh api repos/{owner}/{repo}")
  })

  test("422 is the unsupported-type (or size) refusal", () => {
    expect(httpStory(422, "")).toContain("unsupported type")
    expect(httpStory(422, "")).toMatch(/size/)
  })

  test("anything else keeps the body's first words", () => {
    expect(httpStory(500, '{"message":"boom"}')).toBe('HTTP 500 — {"message":"boom"}')
    expect(httpStory(500, "")).toBe("HTTP 500")
  })
})

describe("sizeOf", () => {
  test("honest at the bottom — a 0 B artifact reads as 0 B", () => {
    expect(sizeOf(0)).toBe("0 B")
    expect(sizeOf(250)).toBe("250 B")
    expect(sizeOf(1023)).toBe("1023 B")
  })

  test("kB and MB above", () => {
    expect(sizeOf(1024)).toBe("1 kB")
    expect(sizeOf(1536)).toBe("2 kB")
    expect(sizeOf(1024 * 1024)).toBe("1.0 MB")
    expect(sizeOf(2.5 * 1024 * 1024)).toBe("2.5 MB")
  })
})

describe("json field", () => {
  test("the field, or null", () => {
    expect(field('{"id":1349937941}', "id")).toBe("1349937941")
    expect(field('{"url":"https://u/1"}', "url")).toBe("https://u/1")
    expect(field('{"other":1}', "url")).toBeNull()
    expect(field("not json", "url")).toBeNull()
    expect(field("{}", "id")).toBeNull()
  })
})

describe("ext", () => {
  test("edge cases", () => {
    expect(ext("a.png")).toBe("png")
    expect(ext("archive.tar.gz")).toBe("gz")
    expect(ext(".hidden")).toBe("")
    expect(ext("noext")).toBe("")
    expect(ext("dot.")).toBe("")
  })
})

const port = Number(process.env.PORT)
const data = process.env.DATA!

const items = (await Array.fromAsync(new Bun.Glob("*").scan(data))).sort()

// the clock exists so a record=true run has visible motion to show
const clock = `<footer id="clock">0.0s</footer><script>const t0=Date.now();setInterval(()=>{document.getElementById("clock").textContent=((Date.now()-t0)/1000).toFixed(1)+"s"},100)</script>`

const html = (body: string) =>
  new Response(`<!doctype html><html><body>${body}${clock}</body></html>`, {
    headers: { "content-type": "text/html; charset=utf-8" },
  })

Bun.serve({
  port,
  async fetch(req) {
    const { pathname } = new URL(req.url)
    if (pathname === "/") {
      const lis = items.map((n) => `<li><a href="/i/${n}">${n}</a></li>`).join("")
      return html(`<h1>items</h1><ul>${lis}</ul>`)
    }
    const m = pathname.match(/^\/i\/([^/]+)$/)
    if (m && items.includes(m[1]!)) {
      const body = await Bun.file(`${data}/${m[1]}`).text()
      return html(`<h1>${m[1]}</h1><pre>${body}</pre><a href="/">back</a>`)
    }
    return new Response("no", { status: 404 })
  },
})

// publish: the shots leave the machine.
// stdout is the markdown block and NOTHING else; saatchi talks on stderr.
import { readdir, stat, unlink } from "node:fs/promises"
import { join } from "node:path"
import { MIME, field, httpStory, isWebm, markdown, mimeFor, siblingsOf, sizeOf, type Landed } from "./upload.ts"

const say = (line: string) => console.error(`saatchi: ${line}`)
const fail = (line: string) => console.error(`saatchi: FAIL ${line}`)

function indent(block: string): string {
  return block
    .trimEnd()
    .split("\n")
    .map((l) => `  ${l}`)
    .join("\n")
}

async function sh(cmd: string[], input?: string): Promise<{ code: number; out: string; err: string }> {
  const proc = Bun.spawn(cmd, {
    // secrets ride stdin (curl -K -), never argv: /proc/*/cmdline is public
    stdin: input == null ? "ignore" : new TextEncoder().encode(input),
    stdout: "pipe",
    stderr: "pipe",
  })
  const [out, err, code] = await Promise.all([
    new Response(proc.stdout).text(),
    new Response(proc.stderr).text(),
    proc.exited,
  ])
  return { code, out, err }
}

async function main(): Promise<number> {
  const t0 = Date.now()
  const secs = () => ((Date.now() - t0) / 1000).toFixed(1)
  const shotsDir = join(process.cwd(), ".saatchi", "shots")

  // — the shots —
  let names: string[]
  try {
    names = (await readdir(shotsDir, { withFileTypes: true }))
      .filter((d) => d.isFile() && !d.name.startsWith("."))
      .map((d) => d.name)
      .sort()
  } catch {
    fail("— no .saatchi/shots/ here; photograph first")
    return 1
  }
  if (names.length === 0) {
    fail("— no shots in .saatchi/shots/; photograph first")
    return 1
  }

  // — repo and token FIRST: transcodes below unlink files, so until gh and
  // the token pass, nothing touches .saatchi/shots/ at all —
  // (`gh repo view --json id` is a GraphQL NODE id; the endpoint 404s on it.
  //  `gh api repos/{owner}/{repo}` — same no-flags convention — has the numeric one.)
  const repo = await sh(["gh", "api", "repos/{owner}/{repo}"])
  if (repo.code !== 0) {
    fail(`— gh could not see a repository from this worktree ↓\n${indent(repo.err)}`)
    return 1
  }
  const repoId = field(repo.out, "id")
  if (!repoId) {
    fail(`— gh api repos/{owner}/{repo}: no .id in the response`)
    return 1
  }
  const auth = await sh(["gh", "auth", "token"])
  const token = auth.out.trim()
  if (auth.code !== 0 || !token) {
    fail("— no token from `gh auth token`; run `gh auth login` first")
    return 1
  }

  // — webm → mp4, in place; ffmpeg's own words on failure (v1's video lesson) —
  // two laws make a failed transcode un-uploadable:
  //   its partial mp4 is deleted, so a re-run can't find a corpse and ship it;
  //   a pre-existing sibling X.mp4 — by ANY case spelling — is never clobbered:
  //   the ambiguous PAIR is refused, both withheld, and the copy says which
  //   file resolves which case (debris: the mp4; two shots: rename one).
  const lost: { file: string; why: string }[] = []
  const files = new Set<string>()
  const webms: string[] = []
  for (const name of names) {
    if (isWebm(name)) webms.push(name)
    else files.add(name)
  }
  for (const name of webms) {
    const mp4 = name.replace(/\.webm$/i, ".mp4")
    const mp4Path = join(shotsDir, mp4)
    // resolve the target against the scan's own strings: an insensitive fs
    // presents clip.mp4 and Clip.mp4 as distinct names for one clobberable
    // inode — the refusal must withhold by THAT name, or it reports while
    // shipping; exists() stays the net for what the scan couldn't name
    const siblings = siblingsOf(files, mp4)
    if (siblings.length > 0 || (await Bun.file(mp4Path).exists())) {
      const victims = siblings.length > 0 ? siblings : [mp4]
      fail(
        `→ ${name}: ${victims.join(" + ")} beside it — refusing the set:\n` +
          `  debris of a killed/failed transcode? delete the mp4 — the webm is the real recording; deleting IT ships the corpse.\n` +
          `  two shots on one stem? rename one. Then re-run.`,
      )
      lost.push({ file: name, why: `${victims.join(" + ")} beside it` })
      for (const victim of victims) {
        files.delete(victim)
        lost.push({ file: victim, why: `withheld — ${name} sits beside it` })
      }
      continue
    }
    const r = await sh([
      "ffmpeg", "-y",
      "-i", join(shotsDir, name),
      "-c:v", "libx264",
      "-pix_fmt", "yuv420p",
      // the moov atom up front is the difference between a player and a black box
      "-movflags", "+faststart",
      mp4Path,
    ])
    const size = await stat(mp4Path).then((s) => s.size).catch(() => 0)
    if (r.code !== 0 || size === 0) {
      // no uploadable artifact survives: delete whatever ffmpeg left —
      // and print ffmpeg's own words on BOTH branches: the 0 B case is
      // precisely where its stderr is the only diagnostic there is
      await unlink(mp4Path).catch(() => {})
      const why = r.code !== 0 ? `ffmpeg exited ${r.code}` : `ffmpeg exited 0 but ${mp4} is 0 B`
      const words = r.err.trim()
      fail(`→ ${name}: ${why}${words ? ` ↓\n${indent(words)}` : ""}`)
      lost.push({ file: name, why })
      continue
    }
    await unlink(join(shotsDir, name)).catch(() => {})
    say(`webm → ${mp4} (${sizeOf(size)})`)
    files.add(mp4)
  }
  const queue = [...files].sort()

  // — the upload: one POST per shot (the settled curl line), in name order —
  const landed: Landed[] = []
  for (const file of queue) {
    const path = join(shotsDir, file)
    const mime = mimeFor(file)
    if (!mime) {
      fail(`→ ${file}: unsupported type (I know: ${Object.keys(MIME).join(" ")})`)
      lost.push({ file, why: "unsupported type" })
      continue
    }
    const qs = new URLSearchParams({ name: file, content_type: mime, repository_id: repoId })
    const t1 = Date.now()
    const r = await sh(
      [
        "curl", "-sS",
        // a stall dies loud and early — NOT a wall clock on a slow pipe:
        "--connect-timeout", "10",
        "--speed-limit", "10240", "--speed-time", "20",
        // --max-time stays the outer bound on a genuinely slow upload
        "--max-time", "120",
        `https://uploads.github.com/user-attachments/assets?${qs}`,
        "-X", "POST",
        "-K", "-",
        "-H", "Accept: application/json",
        "--data-binary", `@${path}`,
        "-w", "\n%{http_code}",
      ],
      `header = "Authorization: Bearer ${token}"\n`,
    )
    if (r.code !== 0) {
      fail(`→ ${file}: curl: ${r.err.trim() || `exit ${r.code}`}`)
      lost.push({ file, why: "curl failed" })
      continue
    }
    const cut = r.out.lastIndexOf("\n")
    const code = Number(r.out.slice(cut + 1))
    const body = cut < 0 ? "" : r.out.slice(0, cut)
    if (!Number.isFinite(code)) {
      fail(`→ ${file}: unparseable curl output`)
      lost.push({ file, why: "unparseable curl output" })
      continue
    }
    if (code >= 200 && code < 300) {
      const url = field(body, "url")
      if (!url) {
        fail(`→ ${file}: HTTP ${code} but no .url in the response ↓\n${indent(body.slice(0, 400))}`)
        lost.push({ file, why: `HTTP ${code}, no .url` })
        continue
      }
      landed.push({ file, url })
      const n = await stat(path).then((s) => s.size).catch(() => 0)
      say(`up   → ${file} (${sizeOf(n)}, ${((Date.now() - t1) / 1000).toFixed(1)}s)`)
      continue
    }
    const story = httpStory(code, body)
    fail(`→ ${file}: ${story}`)
    lost.push({ file, why: story })
  }

  // — stdout: the markdown block; stderr: the account of it —
  if (landed.length > 0) {
    // trailing BLANK line: two `>> body.md` appends stay two blocks — a
    // bare video URL butted onto the block above renders a link, no player
    process.stdout.write(`${markdown(landed)}\n\n`)
  }
  if (lost.length > 0) {
    fail(`— ${lost.length} of ${lost.length + landed.length} did not land:`)
    for (const { file, why } of lost) {
      console.error(`  ${file} — ${why}`)
    }
    if (landed.length > 0) {
      say(`the ${landed.length} that landed are in the markdown on stdout`)
    }
    return 1
  }
  say(`up (${landed.length} shots, ${secs()}s) — markdown on stdout`)
  return 0
}

if (import.meta.main) {
  // NOT process.exit(code): that can drop a buffered stdout write to a pipe —
  // the exact `>> body.md` path. exitCode lets the event loop drain first.
  process.exitCode = await main()
}

import type { Saatchi } from "saatchi"

export default async ({ page, shot }: Saatchi) => {
  await shot("home")
}

import type { Browser, BrowserContext, Page } from "playwright-core"

// Section opt-in is `export const record = true` on evidence.ts (mp4, not stills).

export type Captured = {
  page: Page
  finalize: () => Promise<void>
}

export async function openCaptured(
  browser: Browser,
  opts: { record: boolean; shotsDir: string },
): Promise<Captured> {
  const context: BrowserContext = await browser.newContext(
    opts.record
      ? { recordVideo: { dir: opts.shotsDir, size: { width: 1280, height: 720 } } }
      : {},
  )
  const page = await context.newPage()
  return {
    page,
    finalize: async () => {
      const video = opts.record ? page.video() : null
      await page.close()
      await context.close()
      if (!video) return
      const webm = await video.path()
      const mp4 = `${opts.shotsDir}/record.mp4`
      const proc = Bun.spawn(
        [
          "ffmpeg",
          "-y",
          "-i",
          webm,
          "-c:v",
          "libx264",
          "-pix_fmt",
          "yuv420p",
          "-movflags",
          "+faststart",
          mp4,
        ],
        { stdout: "ignore", stderr: "pipe" },
      )
      const errText = proc.stderr ? await new Response(proc.stderr).text() : ""
      const code = await proc.exited
      const size = Bun.file(mp4).size
      // publish picks up whatever shots/ holds, so a failed transcode must
      // leave NO mp4 behind it — a partial record.mp4 would upload as evidence
      if (code !== 0 || size === 0) {
        try {
          await Bun.file(mp4).unlink()
        } catch {
          // nothing landed to delete
        }
        // ffmpeg's own words ride on BOTH branches: the 0 B case is precisely
        // where its stderr is the only diagnostic there is
        const why = code !== 0 ? `ffmpeg exited ${code}` : "ffmpeg exited 0 but record.mp4 is 0 B"
        const words = errText.trim()
        throw new Error(words ? `${why}:\n${words}` : why)
      }
      try {
        await Bun.file(webm).unlink()
      } catch {
        // leave the webm if unlink fails
      }
    },
  }
}

import { chromium, type Browser, type Page } from "playwright-core"
import { pathToFileURL } from "node:url"
import { openCaptured, type Captured } from "./video.ts"

export type Saatchi = {
  page: Page
  shot: (name: string) => Promise<void>
}

function appAlive(): boolean {
  const pid = Number(process.env.SAATCHI_APP_PID)
  if (!pid) return true
  try {
    process.kill(pid, 0)
    return true
  } catch {
    return false
  }
}

/** 30s slice, extended while the app process is still alive. */
const READY_SLICE_MS = 30_000

async function waitReady(origin: string) {
  let deadline = Date.now() + READY_SLICE_MS
  while (true) {
    if (!appAlive()) {
      throw Object.assign(new Error(`app did not answer 200 on ${origin}`), { saatchi: 2 })
    }
    try {
      const r = await fetch(origin, { redirect: "manual" })
      if (r.status === 200) return
    } catch {
      // not listening yet
    }
    if (Date.now() > deadline) {
      if (appAlive()) deadline = Date.now() + READY_SLICE_MS
      else {
        throw Object.assign(new Error(`app did not answer 200 on ${origin}`), { saatchi: 2 })
      }
    }
    await Bun.sleep(100)
  }
}

function shotNamesFrom(source: string): string[] {
  return [...source.matchAll(/\bshot\(\s*["'`]([^"'`]+)["'`]\s*\)/g)].map((m) => m[1]!)
}

/** Playwright writes this to stderr when PLAYWRIGHT_SKIP_VALIDATE_HOST_REQUIREMENTS is set. */
function muteHostRequirementsChatter() {
  const raw = process.stderr.write.bind(process.stderr)
  process.stderr.write = ((
    chunk: string | Uint8Array,
    encoding?: BufferEncoding | ((err?: Error | null) => void),
    cb?: (err?: Error | null) => void,
  ) => {
    const text = typeof chunk === "string" ? chunk : Buffer.from(chunk).toString()
    if (text.includes("Skipping host requirements validation")) {
      if (typeof encoding === "function") encoding()
      else if (cb) cb()
      return true
    }
    return raw(chunk, encoding as never, cb)
  }) as typeof process.stderr.write
}

function say(line: string) {
  console.log(line)
}

function fail(line: string) {
  console.error(line)
}

function failLine(err: unknown): string {
  if (err && typeof err === "object") {
    const e = err as { name?: string; message?: string }
    const message = (e.message ?? String(err)).split("\n")[0] ?? String(err)
    if (e.name && e.name !== "Error" && !message.startsWith(e.name)) {
      return `${e.name}: ${message}`
    }
    return message
  }
  return String(err)
}

function bootFailed(err: unknown): boolean {
  return Boolean(err && typeof err === "object" && (err as { saatchi?: number }).saatchi === 2)
}

async function main() {
  muteHostRequirementsChatter()
  const port = process.env.PORT
  if (!port) {
    fail("saatchi: FAIL — PORT is not set")
    process.exit(2)
  }
  const origin = `http://127.0.0.1:${port}`
  const evidencePath = process.env.SAATCHI_EVIDENCE
  const shotsDir = process.env.SAATCHI_SHOTS
  if (!evidencePath || !shotsDir) {
    fail("saatchi: FAIL — SAATCHI_EVIDENCE / SAATCHI_SHOTS are not set")
    process.exit(2)
  }
  const startMs = Number(process.env.SAATCHI_START_MS || Date.now())

  let browser: Browser | undefined
  let captured: Captured | undefined
  let failed = false
  let record = false
  let exitCode = 0

  try {
    await waitReady(origin)
    const up = ((Date.now() - startMs) / 1000).toFixed(1)
    say(`saatchi: app  → up ${up}s, ready`)

    const sectionMod = await import(pathToFileURL(evidencePath).href)
    const section = sectionMod.default
    if (typeof section !== "function") {
      throw new Error("evidence.ts must default-export an async function")
    }
    record = sectionMod.record === true
    const names = shotNamesFrom(await Bun.file(evidencePath).text())
    const taken: string[] = []

    const executablePath = process.env.PLAYWRIGHT_LAUNCH_OPTIONS_EXECUTABLE_PATH || undefined
    browser = await chromium.launch({
      headless: true,
      executablePath,
      args: ["--no-sandbox", "--disable-setuid-sandbox", "--disable-dev-shm-usage"],
    })
    captured = await openCaptured(browser, { record, shotsDir })

    try {
      await captured.page.goto(origin, { waitUntil: "load" })
      const shot = async (name: string) => {
        taken.push(name)
        if (record) {
          say(`saatchi: shot → ${name}`)
          return
        }
        const rel = `.saatchi/shots/${name}.png`
        await captured!.page.screenshot({ path: `${shotsDir}/${name}.png`, fullPage: true })
        say(`saatchi: shot → ${rel}`)
      }
      await section({ page: captured.page, shot } satisfies Saatchi)
    } catch (e) {
      failed = true
      const next = names[taken.length] ?? taken.at(-1) ?? "before first shot"
      fail(`saatchi: FAIL at shot "${next}" — ${failLine(e)}`)
    }
  } catch (e) {
    fail(`saatchi: FAIL — ${failLine(e)}`)
    exitCode = bootFailed(e) ? 2 : 1
  } finally {
    if (captured) {
      try {
        await captured.finalize()
      } catch (e) {
        failed = true
        fail(`saatchi: FAIL — ${failLine(e)}`)
      }
    }
    if (browser) {
      try {
        await browser.close()
      } catch {
        // already going down
      }
    }
  }

  if (exitCode === 0 && !failed && record) {
    say(`saatchi: shot → .saatchi/shots/record.mp4`)
  }
  if (failed) exitCode = 1
  if (exitCode) process.exit(exitCode)
}

if (import.meta.main) {
  await main()
}

// publish's pure parts. No io — every branch here is CI territory
// (`bun test upload.test.ts`, run by `nix flake check`).

export const MIME: Record<string, string> = {
  png: "image/png",
  jpg: "image/jpeg",
  jpeg: "image/jpeg",
  gif: "image/gif",
  webp: "image/webp",
  mp4: "video/mp4",
  mov: "video/quicktime",
  webm: "video/webm",
  pdf: "application/pdf",
}

export function ext(name: string): string {
  const dot = name.lastIndexOf(".")
  if (dot <= 0 || dot === name.length - 1) return ""
  return name.slice(dot + 1).toLowerCase()
}

export function mimeFor(name: string): string | null {
  return MIME[ext(name)] ?? null
}

/** playwright records webm; GitHub's player wants mp4. */
export function isWebm(name: string): boolean {
  return ext(name) === "webm"
}

/**
 * Every name in `files` the transcode target could clobber: exact, and
 * case-folded — a case-insensitive filesystem hands `ffmpeg -y clip.mp4`
 * the inode of `Clip.mp4` while reporting both as distinct to readdir.
 * (Refusing case-folded pairs on a case-sensitive fs is deliberate:
 * uniform behavior, and a case-only twin in one directory confuses humans.)
 */
export function siblingsOf(files: ReadonlySet<string>, target: string): string[] {
  const folded = target.toLowerCase()
  return [...files].filter((f) => f.toLowerCase() === folded)
}

/** before-dismiss.png → before-dismiss (the markdown alt text). */
export function stem(name: string): string {
  const e = ext(name)
  return e ? name.slice(0, -(e.length + 1)) : name
}

export type Landed = { file: string; url: string }

/** 0 B is real information — a floored "1 kB" hides exactly the dead artifact. */
export function sizeOf(n: number): string {
  if (n >= 1024 * 1024) return `${(n / 1024 / 1024).toFixed(1)} MB`
  if (n >= 1024) return `${Math.round(n / 1024)} kB`
  return `${n} B`
}

/** {"id":42} → "42" — the field, or null when it isn't there or isn't json. */
export function field(json: string, key: string): string | null {
  try {
    const v = (JSON.parse(json) as Record<string, unknown>)[key]
    return v == null ? null : String(v)
  } catch {
    return null
  }
}

/** `[`, `]`, the escape char itself: any of them in the alt breaks the image syntax. */
function alt(name: string): string {
  return stem(name).replace(/([\\\[\]])/g, "\\$1")
}

/**
 * The ONE markdown block on stdout, ready to paste into a PR body:
 * images embed; everything else is a bare URL on its own line —
 * GitHub renders a player for a video URL, while image syntax on a video
 * renders a player-shaped nothing, and on a pdf, a broken image icon.
 */
export function markdown(landed: Landed[]): string {
  return landed
    .map(({ file, url }) => ((mimeFor(file) ?? "").startsWith("image/") ? `![${alt(file)}](${url})` : url))
    .join("\n\n")
}

/** The endpoint's failure classes, each with its story. */
export function httpStory(code: number, body: string): string {
  if (code === 401 || code === 403) {
    return `uploads.github.com rejected the token (HTTP ${code}) — run \`gh auth login\`; the token needs repo access`
  }
  if (code === 404) {
    return `no repository with this id, or no push rights on it (HTTP 404) — the id came from \`gh api repos/{owner}/{repo}\`; \`gh repo view --json id\` returns a graph node id and 404s here`
  }
  if (code === 422) {
    return `usually an unsupported type — GitHub also 422s on size/validation refusals (HTTP 422)`
  }
  const clip = body.replace(/\s+/g, " ").trim().slice(0, 200)
  return `HTTP ${code}${clip ? ` — ${clip}` : ""}`
}
